import React, {useState} from 'react';
import api from '../lib/api';
import { useNavigate } from 'react-router-dom';

export default function Register(){
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const nav = useNavigate();

  async function submit(e){
    e.preventDefault();
    setError('');
    try{
      const r = await api.post('/auth/register',{name, email, password});
      localStorage.setItem('hr_token', r.data.token);
      localStorage.setItem('hr_user', JSON.stringify(r.data.user));
      alert('Registrasi berhasil! Anda sudah login.');
      nav('/');
    }catch(err){
      const data = err.response?.data;
      let msg = 'Registrasi gagal';
      if (data) {
        if (typeof data.message === 'string') {
          msg = data.message;
        } else if (data.message && typeof data.message === 'object') {
          // Ambil pesan pertama dari object errors {field: [messages]}
          const first = Object.values(data.message).flat?.() || Object.values(data.message);
          msg = Array.isArray(first) ? (first[0] || msg) : String(first || msg);
        } else if (typeof data.error === 'string') {
          msg = data.error;
        }
      }
      setError(msg);
    }
  }

  return (
    <div className="container py-16 max-w-md">
      <h2 className="text-2xl font-semibold">Register - Pembeli</h2>
      <p className="text-gray-600 mb-6">Daftar untuk bisa checkout dan melacak pesanan Anda</p>
      {error && (
        <div className="text-red-600 mb-3">
          {error}
          {(error.toLowerCase().includes('sudah terdaftar') || error.toLowerCase().includes('has already been taken')) && (
            <div className="mt-2">
              Silakan <a href="/login" className="text-primary underline">login</a> dengan email tersebut.
            </div>
          )}
        </div>
      )}
      <form onSubmit={submit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium mb-1">Nama Lengkap</label>
          <input 
            className="input" 
            value={name} 
            onChange={e=>setName(e.target.value)} 
            placeholder="Nama lengkap" 
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Email</label>
          <input 
            type="email"
            className="input" 
            value={email} 
            onChange={e=>setEmail(e.target.value)} 
            placeholder="email@example.com" 
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Password</label>
          <input 
            type="password" 
            className="input" 
            value={password} 
            onChange={e=>setPassword(e.target.value)} 
            placeholder="password" 
            required
          />
        </div>
        <div>
          <button type="submit" className="btn btn-primary w-full">Daftar</button>
        </div>
      </form>
      <div className="text-center mt-4">
        Sudah punya akun? <a href="/login" className="text-primary underline">Login</a>
      </div>
    </div>
  )
}
